credential_keywords := {"password", "passwd", "pwd", "secret", "token", "key", "api_key", "auth_key", "private_key", "secret_key", "access_key", "signing_key", "credential", "creds", "encryption_key", "decrypt_key", "client_secret", "consumer_secret", "shared_secret", "keystore", "truststore"}

password_keywords := {"password", "passwd", "pwd", "secret", "token", "client_secret", "consumer_secret", "shared_secret"}

is_base64(s) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", s)
}

is_hex_key(s) {
    regex.match("^[0-9a-fA-F]{32,}$", s)
}

is_hash_string(s) {
    regex.match("^\\$[0-9a-zA-Z]+\\$", s)
}

looks_like_path(s) {
    regex.match("^[\./][^/]*/[^/]+$", s)
}

is_system_username(s) {
    lower_s := lower(s)
    system_names := {"root", "administrator", "admin", "system", "nobody", "daemon", "bin", "sys", "sync", "games", "man", "lp", "mail", "news", "uucp", "proxy", "www-data", "backup", "list", "irc", "gnats", "nobody", "libuuid", "syslog", "messagebus", "landscape", "sshd", "ntp", "dnsmasq", "vboxadd", "vboxadduser", "sensu", "compute", "telarista", "mistral"}
    system_names[_] == lower_s
}

is_known_insecure_default(s) {
    lower_s := lower(s)
    insecure_defaults := {"password", "secret", "token", "changeme", "cassandra", "default"}
    insecure_defaults[_] == lower_s
}

extract_bracket_components(name) = components {
    # Handle bracket notation like default['a']['b']['c']
    matches := regex.find_all_string_submatch_n("\\['([^']+)'\\]", name, -1)
    components := [m[1] | m := matches[_]]
}

extract_key_components(name) = components {
    # Handle dot notation and underscore separators
    lower_name := lower(name)

    # First try to extract bracket components
    bracket_comps := extract_bracket_components(lower_name)
    count(bracket_comps) > 0

    components := bracket_comps
} else = components {
    lower_name := lower(name)

    # Split by dots
    dot_parts := split(lower_name, ".")

    # For each part, also split by underscores
    components := [part | 
        d := dot_parts[_]
        split_parts := split(d, "_")
        part := split_parts[_]
    ]
}

has_credential_component(name) {
    components := extract_key_components(name)
    comp := components[_]
    kw := credential_keywords[_]
    comp == kw
}

has_password_component(name) {
    components := extract_key_components(name)
    comp := components[_]
    kw := password_keywords[_]
    comp == kw
}

has_store_component(name) {
    components := extract_key_components(name)
    comp := components[_]
    store_names := {"keystore", "truststore"}
    comp == store_names[_]
}

is_external_reference(val) {
    val.ir_type == "VariableReference"
} else {
    val.ir_type == "FunctionCall"
} else {
    val.ir_type == "MethodCall"
}

has_any_external_reference(val) {
    walk(val, [_, node])
    is_external_reference(node)
}

detect_hardcoded_credential(key, value_node) {
    value_node.ir_type == "String"
    value_str := value_node.value
    value_str != ""
    not looks_like_path(value_str)
    not has_any_external_reference(value_node)
    has_password_component(key)
    not is_system_username(value_str)
} else {
    value_node.ir_type == "String"
    value_str := value_node.value
    value_str != ""
    not looks_like_path(value_str)
    not has_any_external_reference(value_node)
    has_password_component(key)
    is_known_insecure_default(value_str)
} else {
    value_node.ir_type == "String"
    value_str := value_node.value
    value_str != ""
    not looks_like_path(value_str)
    not has_any_external_reference(value_node)
    has_store_component(key)
}

get_all_nodes(parent) = nodes {
    nodes := {n |
        walk(parent, [_, n])
        n.ir_type != ""
    }
}

get_variables(parent) = vars {
    nodes := get_all_nodes(parent)
    vars := {n |
        n := nodes[_]
        n.ir_type == "Variable"
    }
}

get_attributes(parent) = attrs {
    nodes := get_all_nodes(parent)
    attrs := {n |
        n := nodes[_]
        n.ir_type == "Attribute"
    }
}

get_hash_entries(parent) = entries {
    nodes := get_all_nodes(parent)
    entries := {{"key": k, "value": v, "parent_line": n.line, "code": n.code} |
        n := nodes[_]
        n.ir_type == "Hash"
        entry := n.value[_]
        entry.key.ir_type == "String"
        k := entry.key.value
        v := entry.value
    }
}

